class Solution {
    public int minimumTimeToInitialState(String word, int k) {
        String original = word;
        StringBuilder sb = new StringBuilder(word);
        int t = 0;
        while (true) {
            String removed = sb.substring(0, k);
            sb.delete(0, k).append(removed);
            t++;
            if (sb.toString().equals(original)) return t;
        }
    }
}

