var minimumTimeToInitialState = function(word, k) {
    const original = word;
    let arr = word.split('');
    let t = 0;
    while (true) {
        const removed = arr.splice(0, k);
        arr = arr.concat(removed);
        t++;
        if (arr.join('') === original) return t;
    }
};

