class Solution {
public:
    int minimumTimeToInitialState(string word, int k) {
        int n = word.size(), t = 1;
        while (t * k < n && word.compare(0, n - t * k, word, t * k, n - t * k) != 0)
            t++;
        return t;
    }
};

